STATUS_WORDS = {"draft": "Draft", "active": "Active", "terminated": "Terminated"}
LIVE_STATUS_FOR_RANGE = ("Active", "Terminated")
FAR_FUTURE = datetime.date.max


def normalize(apps, schema_editor):
    """Lower-case e-mails, map clear status words, backfill ``activated_at``.

    Only unambiguous cases are changed. A stored ``Expired`` becomes ``Active``
    when its end date is already past (the API then derives ``Expired``).
    Anything else is left for ``refuse_conflicts`` to report.
    """
    today = datetime.date.today()
    for name in ("Client", "Vendor", "ClientContact", "VendorContact"):
        model = apps.get_model("masterdata", name)
        for row in model.objects.exclude(email="").iterator():
            lowered = row.email.strip().lower()
            if lowered != row.email:
                model.objects.filter(pk=row.pk).update(email=lowered)

    for name in ("ClientContract", "VendorContract"):
        model = apps.get_model("masterdata", name)
        for row in model.objects.iterator():
            word = (row.status or "").strip().lower()
            if word in STATUS_WORDS:
                status = STATUS_WORDS[word]
            elif word == "expired" and row.expiry_date and row.expiry_date < today:
                status = "Active"
            else:
                continue
            updates = {}
            if status != row.status:
                updates["status"] = status
            if status in LIVE_STATUS_FOR_RANGE and row.effective_date and row.activated_at is None:
                updates["activated_at"] = row.created_at
            if updates:
                model.objects.filter(pk=row.pk).update(**updates)


def _overlaps(a, b):
    a_end = a.expiry_date or FAR_FUTURE
    b_end = b.expiry_date or FAR_FUTURE
    return a.effective_date <= b_end and b.effective_date <= a_end


def refuse_conflicts(apps, schema_editor):
    """Stop, loudly, if live rows would violate the new constraints.

    Nothing is merged, renamed or guessed: which row wins is a data decision.
    """
    problems = []

    for name in ("Client", "Vendor"):
        model = apps.get_model("masterdata", name)
        seen = {}
        for row in model.objects.filter(is_deleted=False).iterator():
            seen.setdefault(row.code.lower(), []).append(str(row.pk))
            if name == "Vendor" and not (0 <= row.rating <= 5):
                problems.append(f"Vendor {row.pk}: rating {row.rating} is outside 0 to 5")
            if name == "Client" and row.total_billed_usd is not None and row.total_billed_usd < 0:
                problems.append(f"Client {row.pk}: negative total_billed_usd")
        for code, ids in seen.items():
            if len(ids) > 1:
                problems.append(
                    f"{name}: code {code!r} used by {len(ids)} rows ({', '.join(ids[:5])})"
                )

    for name, parent in (("ClientContact", "client_id"), ("VendorContact", "vendor_id")):
        model = apps.get_model("masterdata", name)
        primaries, emails = {}, {}
        for row in model.objects.filter(is_deleted=False).iterator():
            owner = getattr(row, parent)
            if row.is_primary:
                primaries.setdefault(owner, []).append(str(row.pk))
            if row.email:
                emails.setdefault((owner, row.email.lower()), []).append(str(row.pk))
        for owner, ids in primaries.items():
            if len(ids) > 1:
                problems.append(
                    f"{name}: {len(ids)} primary contacts for {parent} {owner} ({', '.join(ids[:5])})"
                )
        for (owner, _email), ids in emails.items():
            if len(ids) > 1:
                problems.append(
                    f"{name}: one e-mail used by {len(ids)} contacts of {parent} {owner} ({', '.join(ids[:5])})"
                )

    for name, parent in (("ClientContract", "client_id"), ("VendorContract", "vendor_id")):
        model = apps.get_model("masterdata", name)
        numbers, ranges = {}, {}
        for row in model.objects.filter(is_deleted=False).iterator():
            owner = getattr(row, parent)
            numbers.setdefault((owner, row.contract_number.lower()), []).append(str(row.pk))
            if row.status not in STATUS_WORDS.values():
                problems.append(
                    f"{name} {row.pk}: status {row.status!r} is not Draft, Active or Terminated"
                )
            if row.status == "Active" and row.effective_date is None:
                problems.append(f"{name} {row.pk}: Active without an effective_date")
            if row.effective_date and row.expiry_date and row.expiry_date < row.effective_date:
                problems.append(f"{name} {row.pk}: expiry_date is before effective_date")
            covers = row.status == "Active" or (
                row.status == "Terminated" and row.activated_at is not None
            )
            if covers and row.effective_date and (row.type or "").lower() == "msa":
                ranges.setdefault(owner, []).append(row)
        for (owner, number), ids in numbers.items():
            if len(ids) > 1:
                problems.append(
                    f"{name}: contract number {number!r} used {len(ids)} times for {parent} {owner} ({', '.join(ids[:5])})"
                )
        for owner, rows in ranges.items():
            for i, a in enumerate(rows):
                for b in rows[i + 1 :]:
                    if _overlaps(a, b):
                        problems.append(
                            f"{name}: MSAs {a.pk} and {b.pk} overlap for {parent} {owner}"
                        )

    if problems:
        raise RuntimeError(
            "masterdata 0007 cannot add its constraints: existing rows conflict "
            "(client/vendor code, one primary contact and one e-mail per contact owner, contract number, "
            "status Draft/Active/Terminated, dates, overlapping MSAs, vendor rating). "
            "Resolve these rows, then migrate again:\n  " + "\n  ".join(problems[:60])
        )


def settle_deferred_checks(apps, schema_editor):
    """Fire the foreign-key checks queued by the data steps (PostgreSQL only).

    PostgreSQL refuses to create an index on a table with pending deferred
    trigger events from earlier statements in the same transaction.
    """
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")
        schema_editor.execute("SET CONSTRAINTS ALL DEFERRED")


